import{_ as n,a0 as o,w as p,s as d,ao as r,I as l,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Linux 上鎖定虛擬控制台會話 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上鎖定虛擬控制台會話 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上鎖定虛擬控制台會話 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上鎖定虛擬控制台會話 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181012 How To Lock Virtual Console Sessions On Linux","title":"如何在 Linux 上鎖定虛擬控制台會話","tag":"201810","desc":""},"relativePath":"201810/20181012 How To Lock Virtual Console Sessions On Linux.md","filePath":"[post].md"}'),h={name:"201810/20181012 How To Lock Virtual Console Sessions On Linux.md"};function c(k,s,g,u,b,f){const e=o("Link");return p(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上鎖定虛擬控制台會話" tabindex="-1">如何在 Linux 上鎖定虛擬控制台會話 <a class="header-anchor" href="#如何在-linux-上鎖定虛擬控制台會話" aria-label="Permalink to “如何在 Linux 上鎖定虛擬控制台會話”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/vlock-720x340.png" alt=""></p><p>當你在共享的系統上工作時，你可能不希望其他用户偷窺你的控制台中看你在做什麼。如果是這樣，我知道有個簡單的技巧來鎖定自己的會話，同時仍然允許其他用户在其他虛擬控制台上使用該系統。要感謝 <strong>Vlock</strong>（<strong>V</strong>irtual Console <strong>lock</strong>），這是一個命令列程序，用於鎖定 Linux 控制台上的一個或多個會話。如有必要，你可以鎖定整個控制台並完全禁用虛擬控制台切換功能。Vlock 對於有多個用户訪問控制台的共享 Linux 系統特別有用。</p><h3 id="安裝-vlock" tabindex="-1">安裝 Vlock <a class="header-anchor" href="#安裝-vlock" aria-label="Permalink to “安裝 Vlock”">​</a></h3><p>在基於 Arch 的系統上，Vlock 軟件包被替換為默認預安裝的 <strong>kpd</strong> 包，因此你無需為安裝煩惱。</p><p>在 Debian、Ubuntu、Linux Mint 上，運行以下命令來安裝 Vlock：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install vlock</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install vlock</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install vlock</span></span></code></pre></div><h3 id="在-linux-上鎖定虛擬控制台會話" tabindex="-1">在 Linux 上鎖定虛擬控制台會話 <a class="header-anchor" href="#在-linux-上鎖定虛擬控制台會話" aria-label="Permalink to “在 Linux 上鎖定虛擬控制台會話”">​</a></h3><p>Vlock 的一般語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vlock [ -acnshv ] [ -t &lt;timeout&gt; ] [ plugins... ]</span></span></code></pre></div><p>這裏：</p><ul><li><code>a</code> —— 鎖定所有虛擬控制台會話，</li><li><code>c</code> —— 鎖定當前虛擬控制台會話，</li><li><code>n</code> —— 在鎖定所有會話之前切換到新的空控制台，</li><li><code>s</code> —— 禁用 SysRq 鍵機制，</li><li><code>t</code> —— 指定屏保插件的超時時間，</li><li><code>h</code> —— 顯示幫助，</li><li><code>v</code> —— 顯示版本。</li></ul><p>讓我舉幾個例子。</p><h4 id="_1、-鎖定當前控制台會話" tabindex="-1">1、 鎖定當前控制台會話 <a class="header-anchor" href="#_1、-鎖定當前控制台會話" aria-label="Permalink to “1、 鎖定當前控制台會話”">​</a></h4><p>在沒有任何參數的情況下運行 Vlock 時，它默認鎖定當前控制台會話 （TYY）。要解鎖會話，你需要輸入當前用户的密碼或 root 密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/vlock-1-1.gif" alt=""></p><p>你還可以使用 <code>-c</code> 標誌來鎖定當前的控制台會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -c</span></span></code></pre></div><p>請注意，此命令僅鎖定當前控制台。你可以按 <code>ALT+F2</code> 切換到其他控制台。有關在 TTY 之間切換的更多詳細信息，請參閲以下指南。</p><p>此外，如果系統有多個用户，則其他用户仍可以訪問其各自的 TTY。</p><h4 id="_2、-鎖定所有控制台會話" tabindex="-1">2、 鎖定所有控制台會話 <a class="header-anchor" href="#_2、-鎖定所有控制台會話" aria-label="Permalink to “2、 鎖定所有控制台會話”">​</a></h4><p>要同時鎖定所有 TTY 並禁用虛擬控制台切換功能，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -a</span></span></code></pre></div><p>同樣，要解鎖控制台會話，只需按下回車鍵並輸入當前用户的密碼或 root 用户密碼。</p><p>請記住，<strong>root 用户可以隨時解鎖任何 vlock 會話</strong>，除非在編譯時禁用。</p><h4 id="_3、-在鎖定所有控制台之前切換到新的虛擬控制台" tabindex="-1">3、 在鎖定所有控制台之前切換到新的虛擬控制台 <a class="header-anchor" href="#_3、-在鎖定所有控制台之前切換到新的虛擬控制台" aria-label="Permalink to “3、 在鎖定所有控制台之前切換到新的虛擬控制台”">​</a></h4><p>在鎖定所有控制台之前，還可以使 Vlock 從 X 會話切換到新的空虛擬控制台。為此，請使用 <code>-n</code> 標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -n</span></span></code></pre></div><h4 id="_4、-禁用-sysrq-機制" tabindex="-1">4、 禁用 SysRq 機制 <a class="header-anchor" href="#_4、-禁用-sysrq-機制" aria-label="Permalink to “4、 禁用 SysRq 機制”">​</a></h4><p>你也許知道，魔術 SysRq 鍵機制允許用户在系統死機時執行某些操作。因此，用户可以使用 SysRq 解鎖控制台。為了防止這種情況，請傳遞 <code>-s</code> 選項以禁用 SysRq 機制。請記住，這個選項只適用於有 <code>-a</code> 選項的時候。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -sa</span></span></code></pre></div><p>有關更多選項及其用法，請參閲幫助或手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -h</span></span>
<span class="line"><span>$ man vlock</span></span></code></pre></div><p>Vlock 可防止未經授權的用户獲得控制台訪問權限。如果你在為 Linux 尋找一個簡單的控制台鎖定機制，那麼 Vlock 值得一試！</p><p>就是這些了。希望這篇文章有用。還有更多好東西。敬請關注！</p><p>乾杯!</p><hr>`,42)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-lock-virtual-console-sessions-on-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-lock-virtual-console-sessions-on-linux/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const C=n(h,[["render",c]]);export{v as __pageData,C as default};
